def IM(name, h=190): return FIG(name).replace('<img class="fig"', f'<img style="height: {h}px; border-radius: 12px; border: 3px solid #D5DEEA; vertical-align: middle; background: #fff"')
def SV(svg, h=300): return svg.replace('<svg class="svgfig', f'<svg style="height: {h}px; width: auto; vertical-align: middle" class="svgfig')
def K(t): return f'<b style="color: #C2410C">{t}</b>'
def L(*a): return ' ، '.join(a)
def PR(a, b): return f'({a} ، {b})'
